/**
 * A StringBuilder is a mutable sequence of characters. This class provides an API similar to Java's StringBuilder.
 * For more information, view the forum post at: https://devforum.roblox.com/t/stringbuilder-library-much-faster-concatenation/475708.
 */
declare interface StringBuilder extends Array<string> {

    /**
     * Append a string to the end of the string builder.
     * 
     * @param str The string to append.
     */
    append(str: unknown): StringBuilder;

    /**
     * Append strings to the end of the string builder.
     * 
     * @param str The strings to append.
     */
    appendAll(...str: unknown[]): StringBuilder;

    /**
     * Convert the string builder to a string.
     */
    toString(): string;
}

/**
 * Constructor class for {@link StringBuilder}.
 */
declare interface StringBuilderConstructor {

    /**
     * Construct a new string builder with the given strings.
     */
    new(...str: string[]): StringBuilder;
}

declare const StringBuilder: StringBuilderConstructor;

export = StringBuilder;